\section{Proof of the main result}\label{sec:main_proof}

We now prove \Cref{thm:intro_main}. The proof consists of two main ingredients: a density matrix that is low-rank but whose partial transpose is positive definite (\Cref{sec:unperturbed_separable}), and a perturbation of that density matrix that necessarily has large Schmidt number (\Cref{sec:perturb}).

\subsection{A low-rank state with positive-definite partial transpose}\label{sec:unperturbed_separable}

For an integer $d \geq 0$, let $V_d : \C^{d+1} \to \Sym^d(\C^2)$ be the isometry defined by
\begin{align}\label{eq:Vd_defn}
    V_d\ket{j} = \sqrt{\frac{1}{\binom{d}{j}}}\sum_{\substack{I \in \{0,1\}^d \\ |I|=j}} \ket{i_1} \otimes \ket{i_2} \otimes \cdots \otimes \ket{i_d}
\end{align}
for $j \in \{0,1,\ldots,d\}$. That is, $V_d\ket{j}$ are the normalized Dicke states, which form an orthonormal basis of $\Sym^d(\C^2)$.

Write $P_d := V_dV_d^*$ for the orthogonal projection onto $\Sym^d(\C^2) \subseteq (\C^2)^{\otimes d}$. We can now introduce the state that we will need:

\begin{lemma}\label{lem:low_rank_pt_high_rank}
    Let $m,n \geq 2$ be integers and define the state $\sigma_{m,n} \in \Density(\C^m \otimes \C^n)$ by
    \[
        \sigma_{m,n} := \frac{1}{m+n-1}\big(V_{m-1}^* \otimes V_{n-1}^*\big) P_{m+n-2} \big(V_{m-1}\otimes V_{n-1}\big),
    \]
    where $V_{m-1}$ and $V_{n-1}$ are as in \Cref{eq:Vd_defn} and $P_{m+n-2} := V_{m+n-2}V_{m+n-2}^*$. Then
    \begin{align}\label{eq:lam_min_sig}
        \rank(\sigma_{m,n}) = m + n - 1 \quad \text{and} \quad \lambda_{\min}\big(\sigma_{m,n}^\Gamma\big) = \frac{1}{(m+n-1)\binom{m+n-2}{m-1}}.
    \end{align}
\end{lemma}

\begin{proof}
    The claim that $\rank(\sigma_{m,n}) = m + n - 1$ follows from the facts that $\rank(\sigma_{m,n}) = \rank(P_{m+n-2})$ (since $\Sym^{m+n-2}(\C^2) \subseteq \Sym^{m-1}(\C^2) \otimes \Sym^{n-1}(\C^2)$) and $\rank(P_{m+n-2}) = m + n - 1$. This also shows that $\sigma_{m,n}$ is indeed a state as claimed: since $P_{m+n-2}$ is an orthogonal projection of rank $m+n-1$, $P_{m+n-2}/(m+n-1)$ is a density matrix, and $\sigma_{m,n}$ is isometrically equivalent to it.

    The claim about $\lambda_{\min}\big(\sigma_{m,n}^\Gamma\big)$ comes from \cite[Equation~(8)]{LSEBM25}.
\end{proof}

In particular, notice that \Cref{eq:lam_min_sig} implies that the minimal eigenvalue of $\sigma_{m,n}^\Gamma$ is strictly positive, so it has full rank, despite $\sigma_{m,n}$ itself having very low rank.

\subsection{Perturbation}\label{sec:perturb}

In this section, we introduce a direction in which we can perturb the state $\sigma_{m,n}$ from \Cref{sec:unperturbed_separable} so as to construct our desired high-Schmidt-number PPT quantum state. We let $\Q$ denote the rational numbers and let $\overline{\Q}$ be the algebraic numbers. To start, consider the $mn$ real numbers
\begin{align}\label{eq:thetaG}
    g_{i,j} = \exp\big(2^{(in+j)/(mn)}\big)
\end{align}
for $i \in \{0,1,2,\ldots,m-1\}$ and $j \in \{0,1,2,\ldots,n-1\}$.

\begin{lemma}\label{lem:alg_ind}
    The set of $mn$ numbers $\{g_{i,j}\}$ defined by \Cref{eq:thetaG} is algebraically independent over $\overline{\Q}$.
\end{lemma}

\begin{proof}
    The polynomial $x^{mn} - 2$ is irreducible over $\Q$ by Eisenstein's criterion (with the prime $2$), so it is the minimal polynomial of $\theta := 2^{1/(mn)}$. Since this polynomial has degree $mn$, the numbers $1$, $\theta$, $\theta^2$, $\ldots$, $\theta^{mn-1}$ are linearly independent over $\Q$ (since if they weren't linearly independent over $\Q$ then there would exist a degree-$(mn-1)$ polynomial with $\theta$ as a root, contradicting minimality of $x^{mn} - 2$).

    Suppose (for the sake of establishing a contradiction) that $\{g_{i,j}\}$ is not algebraically independent over $\overline{\Q}$. Then there exists a nonzero polynomial $p \in \overline{\Q}[x_0,x_1,\ldots,x_{mn-1}]$ such that
    \[
        p\big(\exp(\theta^0), \exp(\theta^1), \ldots, \exp(\theta^{mn-1})\big) = 0.
    \]
    Write $p$ as a finite sum of distinct monomials:
    \[
        p(x_0, x_1, \ldots, x_{mn-1}) = \sum_{\boldsymbol{\nu}} c_{\boldsymbol{\nu}} \prod_{q=0}^{mn-1} x_q^{\nu_q},
    \]
    where the sum is over all tuples $\boldsymbol{\nu} = (\nu_0, \nu_1, \ldots, \nu_{mn-1}) \in \N^{mn}$, $c_{\boldsymbol{\nu}} \in \overline{\Q}$ for all $\boldsymbol{\nu}$, and at least one (and only finitely many) of the coefficients $c_{\boldsymbol{\nu}}$ is nonzero. Plugging in $x_q = \exp(\theta^q)$ gives
    \begin{align}\label{eq:alg_indep_equation}
        0 & = \sum_{\boldsymbol{\nu}} c_{\boldsymbol{\nu}}\prod_{q=0}^{mn-1} \exp(\theta^q)^{\nu_q} = \sum_{\boldsymbol{\nu}} c_{\boldsymbol{\nu}}\exp\left( \sum_{q=0}^{mn-1} \nu_q\theta^q \right).
    \end{align}

    We claim that the quantities
    \[
        \sum_{q=0}^{mn-1} \nu_q\theta^q
    \]
    are all algebraic and distinct. Indeed, they are algebraic since $\theta$ is algebraic (and $\nu_q \in \N$ for all $q$). To see that they are distinct, notice that if two multi-indices $\boldsymbol{\nu}$ and $\boldsymbol{\mu}$ gave the same quantity then we would have
    \[
        \sum_{q=0}^{mn-1}(\nu_q-\mu_q)\theta^q = 0.
    \]
    However, linear independence of $1, \theta, \theta^2, \ldots, \theta^{mn-1}$ over $\Q$ then implies that $\nu_q = \mu_q$ for every $q$, so $\boldsymbol{\nu} = \boldsymbol{\mu}$.

    It follows that \Cref{eq:alg_indep_equation} is a nontrivial linear equation over $\overline{\Q}$ of exponentials of distinct algebraic numbers. This contradicts the Lindemann--Weierstrass theorem (see \cite{Pop24}, for example). We thus conclude that $\{g_{i,j}\}$ is algebraically independent over $\overline{\Q}$, as desired.
\end{proof}

Our main technical result of this section shows that any vector in $\C^m \otimes \C^n$ whose entries are the numbers $\{g_{i,j}\}$ (in any order) must ``point outside of'' any low-dimensional subspace with an algebraic basis:

\begin{lemma}\label{lem:perturb_algebraic}
    Let $m,n \geq 2$ be positive integers, let $\cS \subseteq \C^m \otimes \C^n$ be a subspace with a basis whose entries all belong to $\overline{\Q}$, and suppose $r \in \{0, 1, 2, \ldots, \min\{m,n\}-1\}$ satisfies
    \begin{align}\label{eq:dimension_condition}
        (m-r)(n-r) > \dim(\cS).
    \end{align}
    Suppose further that $\mathbf{v} \in \C^m \otimes \C^n$ is a vector with the numbers from \Cref{eq:thetaG} as its $mn$ entries (in any order), and that $z \in \C$ and $\mathbf{w} \in \cS$ are such that
    \begin{align}\label{eq:perturb_avoid}
        \SR(\mathbf{w} + z\mathbf{v}) \leq r.
    \end{align}
    Then $z = 0$. Furthermore, $\mathbf{v} \notin \cS$.
\end{lemma}

\begin{proof}
    We refer the reader to~\cite{Har92} for the algebraic geometry background used in this proof. Let
    \[
        \cD_r := \{\mathbf{x} \in \C^m \otimes \C^n : \SR(\mathbf{x}) \leq r\}.
    \]
    Under the usual identification of $\C^m \otimes \C^n$ with the set of $m \times n$ complex matrices, this is the determinantal variety of matrices of rank at most $r$. In particular, $\dim(\cD_r) = r(m+n-r)$, and $\cD_r$ is the common zero set of the $(r+1) \times (r+1)$ minors of the corresponding coefficient matrix (see e.g.~\cite[Proposition 12.2]{Har92} or~\cite[Lemma~4]{CMW08}).

    Consider the algebraic set
    \[
        Z := \closure{\cS + \cD_r},
    \]
    where the ``$+$'' here is the usual Minkowski sum and ``$\closure{\phantom{\cS}}$'' denotes the Zariski closure. Since the map $F : \cS \times \cD_r \rightarrow \cS + \cD_r \subseteq \C^m \otimes \C^n$ defined by $F(\mathbf{a},\mathbf{b}) = \mathbf{a} + \mathbf{b}$ is a polynomial map, we have
    \begin{align*}
        \dim(Z) & \leq \dim(\cS) + \dim(\cD_r) = \dim(\cS) + r(m+n-r) < mn,
    \end{align*}
    where the first inequality follows from e.g.~\cite[Theorem 11.12]{Har92}), and the second follows from~\Cref{eq:dimension_condition}. It follows that $Z$ is a proper algebraic subset of $\C^m \otimes \C^n$.

    We claim that $Z$ is cut out by polynomials with coefficients in $\overline{\Q}$. To see this, it suffices to notice that $\cS$ is cut out by polynomials with coefficients in $\overline{\Q}$ (since it has a basis with entries in this set), $\cD_r$ is cut out by polynomials with coefficients in $\Q$ (in fact, these polynomials are determinants, which have coefficients in $\{-1,0,1\}$), and $F$ has coefficients in $\Q$.

    Now suppose that \Cref{eq:perturb_avoid} holds for some $z \neq 0$. Then $\mathbf{w} + z\mathbf{v} \in \cD_r$, so
    \[
        \mathbf{v} = \frac{\mathbf{w}+z\mathbf{v}}{z} - \frac{\mathbf{w}}{z} \in \cD_r + \cS \subseteq Z.
    \]
    However, \Cref{lem:alg_ind} tells us that the $mn$ entries of $\mathbf{v}$ are algebraically independent over $\overline{\Q}$. As a result, $\mathbf{v}$ cannot belong to $Z$, since $\dim(Z) < mn$ (membership in $Z$ would imply the existence of a nonzero polynomial $p$ with coefficients in $\overline{\Q}$ such that $p(\mathbf{v}) = 0$). We thus conclude that $z \neq 0$ is impossible, so $z = 0$.

    Finally, since $\cS \subseteq Z$, the fact that $\mathbf{v} \notin Z$ implies $\mathbf{v} \notin \cS$, which completes the proof.
\end{proof}

\subsection{Finishing the proof}\label{sec:finalize_proof}

We now put together the ingredients from the two previous subsections in order to prove our main result. In particular, the following theorem immediately implies \Cref{thm:intro_main}:

\begin{theorem}\label{thm:main_explicit}
    Let $m,n \geq 2$ be positive integers, let $\sigma_{m,n} \in \Density(\C^m \otimes \C^n)$ be as in \Cref{lem:low_rank_pt_high_rank}, and let $\mathbf{v} \in \C^m \otimes \C^n$ be a vector with the numbers from \Cref{eq:thetaG} as its $mn$ entries (in any order). Define
    \begin{align}\label{eq:explicitg}
        C := \frac{1}{(m+n-1)\binom{m+n-2}{m-1}} \quad \text{and} \quad \ket{g} := \frac{\mathbf{v}}{\|\mathbf{v}\|}.
    \end{align}
    Then the state
    \[
        \rho := \frac{1}{2C+1}\sigma_{m,n} + \frac{2C}{2C+1}\ketbra{g}
    \]
    is PPT and has
    \begin{align}\label{eq:SN_bound}
        \SN(\rho) \geq \left\lceil \frac{m + n - \sqrt{(m - n)^2 + 4(m + n - 1)}}{2} \right\rceil.
    \end{align}
\end{theorem}

\begin{proof}
    We first show that $\rho$ is PPT. For every unit vector $\ket{g}$, $\lambda_{\min}\big((\ketbra{g})^\Gamma\big) \geq -1/2$. Indeed, if the Schmidt coefficients of $\ket{g}$ are $\gamma_1 \geq \gamma_2 \geq \cdots \geq \gamma_{\min\{m,n\}} \geq 0$ then the negative eigenvalues of $(\ketbra{g})^\Gamma$ are $-\gamma_i\gamma_j$ \cite[Lemma~1]{JP18}, which are no smaller than $-1/2$ (since $2\gamma_i\gamma_j \leq \gamma_i^2 + \gamma_j^2 \leq 1$). Together with $\lambda_{\min}\big(\sigma_{m,n}^\Gamma) = C$ from \Cref{eq:lam_min_sig}, this gives
    \begin{align*}
        \lambda_{\min}\big(\rho^\Gamma\big) & \geq \frac{1}{2C+1}\lambda_{\min}\big(\sigma_{m,n}^\Gamma\big) + \frac{2C}{2C+1}\lambda_{\min}\big((\ketbra{g})^\Gamma\big) \geq \frac{C}{2C+1} - \frac{C}{2C+1} = 0,
    \end{align*}
    so $\rho$ has positive partial transpose.

    To bound the Schmidt number of $\rho$, first notice that if
    \begin{align}\label{eq:r_value}
        r := \left\lceil \frac{m + n - \sqrt{(m - n)^2 + 4(m + n - 1)}}{2} \right\rceil - 1
    \end{align}
    then $(m-r)(n-r) > m + n - 1 = \rank(\sigma_{m,n})$ (indeed, solving the quadratic equation $(m-r)(n-r) = m + n - 1$ for $r$ gives exactly the quantity inside the ceiling in \Cref{eq:r_value}, and our choice of $r$ is strictly smaller than this quantity).

    Now suppose (for the sake of establishing a contradiction) that $\SN(\rho) \leq r$, so that
    \begin{align}\label{eq:proof_rho_sr_r_decomp}
        \rho = \sum_j p_j \ketbra{x_j}
    \end{align}
    for some probability vector $\mathbf{p}$ and unit vectors $\ket{x_j} \in \im(\rho) = \spn(\im(\sigma_{m,n}), \ket{g})$ with $\SR(\ket{x_j}) \leq r$ for all $j$. Since the entries of $\sigma_{m,n}$ are all in $\overline{\Q}$, $\im(\sigma_{m,n})$ has a basis consisting of vectors with entries from $\overline{\Q}$. \Cref{lem:perturb_algebraic} (applied to $\cS = \im(\sigma_{m,n})$) then shows that $\ket{x_j} \in \im(\sigma_{m,n})$ for all $j$. However, the decomposition of \Cref{eq:proof_rho_sr_r_decomp} then implies that $\im(\rho) \subseteq \im(\sigma_{m,n})$, which contradicts the fact that $\ket{g} \notin \im(\sigma_{m,n})$ (which also comes from \Cref{lem:perturb_algebraic}). This completes the proof.
\end{proof}

The particular scalars that were used in the definition of $\rho$ in \Cref{thm:main_explicit} are only required to show that $\rho$ is PPT; the same Schmidt number guarantee holds for every nontrivial convex combination of $\sigma_{m,n}$ and $\ketbra{g}$. As a result, the same proof shows that the state
\[
    \rho_p := (1-p)\sigma_{m,n} + p\ketbra{g}
\]
is PPT and satisfies the Schmidt number bound of \Cref{eq:SN_bound} for all $p \in (0,2C/(2C+1)]$.

